## 3. Result-Generation Logic (form data → recommendation)

The module-specific result logic is defined **inline** in the Compass page (the `evaluate` function plus `VRInputs`, `defaultInputs`, and the PDF content assembly in `handleExportPDF`), not in a separate lib file.

Source: `client/src/pages/VasectomyReversalCompass.tsx`

```typescript
interface VRInputs {
  yearsSinceVasectomy: number;
  priorVasectomyReversal: boolean;
  spermInVas: boolean | null;
  partnerAge: number;
  partnerFertilityEvaluated: boolean;
  partnerFertilityNormal: boolean;
  antispermAntibodies: boolean;
  epididymalObstruction: boolean;
  testisVolume: "normal" | "reduced" | "atrophic";
  fshLevel: number;
  previousChildrenWithPartner: boolean;
  patientAge: number;
}

const defaultInputs: VRInputs = {
  yearsSinceVasectomy: 0,
  priorVasectomyReversal: false,
  spermInVas: null,
  partnerAge: 0,
  partnerFertilityEvaluated: false,
  partnerFertilityNormal: true,
  antispermAntibodies: false,
  epididymalObstruction: false,
  testisVolume: "normal",
  fshLevel: 0,
  previousChildrenWithPartner: false,
  patientAge: 0,
};

function evaluate(inputs: VRInputs) {
  const warnings: string[] = [];
  const rationale: string[] = [];
  const references = [
    "Belker AM, et al. Results of 1,469 microsurgical vasectomy reversals by the Vasovasostomy Study Group. J Urol. 1991;145(3):505-511.",
    "Kolettis PN, Thomas AJ Jr. Vasoepididymostomy for vasectomy reversal: a critical assessment in the era of intracytoplasmic sperm injection. J Urol. 1997;158(2):467-470.",
    "Practice Committee of the American Society for Reproductive Medicine. Vasectomy reversal. Fertil Steril. 2015;104(3):e1-e8.",
    "Wosnitzer MS, Goldstein M. Obstructive azoospermia. Urol Clin North Am. 2014;41(1):83-95.",
    "Jarvi K, et al. CUA Guideline: The workup of azoospermic males. Can Urol Assoc J. 2010;4(3):163-167.",
  ];

  // Obstructive interval prognosis
  let patencyRate = "";
  let pregnancyRate = "";
  if (inputs.yearsSinceVasectomy <= 3) { patencyRate = "97%"; pregnancyRate = "76%"; }
  else if (inputs.yearsSinceVasectomy <= 8) { patencyRate = "88%"; pregnancyRate = "53%"; }
  else if (inputs.yearsSinceVasectomy <= 14) { patencyRate = "79%"; pregnancyRate = "44%"; }
  else { patencyRate = "71%"; pregnancyRate = "30%"; }

  rationale.push(`Obstructive interval of ${inputs.yearsSinceVasectomy} years: expected patency rate ~${patencyRate}, pregnancy rate ~${pregnancyRate} (Vasovasostomy Study Group, Belker 1991).`);

  // Procedure type
  let procedure = "Vasovasostomy (VV)";
  let procedureRationale = "Intraoperative vasal fluid showing sperm or sperm heads favors vasovasostomy.";
  if (inputs.epididymalObstruction || inputs.spermInVas === false) {
    procedure = "Vasoepididymostomy (VE)";
    procedureRationale = "Absence of sperm in vasal fluid or epididymal obstruction indicates vasoepididymostomy is required.";
    warnings.push("Vasoepididymostomy is technically more demanding; refer to high-volume microsurgeon.");
  }
  rationale.push(procedureRationale);

  // Partner age
  if (inputs.partnerAge > 37) {
    warnings.push(`Partner age ${inputs.partnerAge}: diminished ovarian reserve likely. Consider concurrent IVF/ICSI planning.`);
    rationale.push("AUA/ASRM guidelines recommend discussing IVF/ICSI as alternative when female partner is >37 years.");
  }

  // Anti-sperm antibodies
  if (inputs.antispermAntibodies) {
    warnings.push("Anti-sperm antibodies detected: may reduce fertilization rates even after successful reversal.");
  }

  // FSH
  if (inputs.fshLevel > 7.6) {
    warnings.push(`Elevated FSH (${inputs.fshLevel} mIU/mL) suggests impaired spermatogenesis; reversal success may be reduced.`);
  }

  // Testis volume
  if (inputs.testisVolume === "atrophic") {
    warnings.push("Testicular atrophy suggests primary spermatogenic failure; reversal may not restore fertility.");
    rationale.push("Testicular atrophy is associated with poor reversal outcomes; sperm banking at time of reversal is strongly recommended.");
  }

  // Prior reversal
  if (inputs.priorVasectomyReversal) {
    warnings.push("Prior failed reversal: success rates are lower; vasoepididymostomy more likely required.");
  }

  const recommendation = warnings.filter(w => w.includes("atrophy") || w.includes("spermatogenic failure")).length > 0 ? "caution" : "indicated";
  const cor = inputs.yearsSinceVasectomy <= 14 ? "I" : "IIa";
  const loe = "B";

  return { recommendation, procedure, patencyRate, pregnancyRate, cor, loe, warnings, rationale, references };
}
```

