const handleExportPDF = () => {
  if (!result) return;
  const content = `VASECTOMY REVERSAL CLINICAL DECISION SUPPORT

PATIENT PROFILE
Patient Age: ${inputs.patientAge} years
Years Since Vasectomy: ${inputs.yearsSinceVasectomy}
Prior Reversal Attempt: ${inputs.priorVasectomyReversal ? "Yes" : "No"}
Sperm in Vasal Fluid: ${inputs.spermInVas === null ? "Unknown" : inputs.spermInVas ? "Yes" : "No"}
Epididymal Obstruction: ${inputs.epididymalObstruction ? "Yes" : "No"}
Testis Volume: ${inputs.testisVolume}
FSH Level: ${inputs.fshLevel} mIU/mL
Anti-Sperm Antibodies: ${inputs.antispermAntibodies ? "Yes" : "No"}
Partner Age: ${inputs.partnerAge} years
Partner Fertility Evaluated: ${inputs.partnerFertilityEvaluated ? "Yes" : "No"}
Partner Fertility Normal: ${inputs.partnerFertilityNormal ? "Yes" : "No"}

ASSESSMENT RESULT
Recommendation: ${result.recommendation.toUpperCase()}
Recommended Procedure: ${result.procedure}
Expected Patency Rate: ${result.patencyRate}
Expected Pregnancy Rate: ${result.pregnancyRate}
Class of Recommendation: ${result.cor}
Level of Evidence: ${result.loe}

CLINICAL RATIONALE
${result.rationale.map((r, i) => `${i + 1}. ${r}`).join("\n")}

${result.warnings.length > 0 ? `CLINICAL WARNINGS\n${result.warnings.map((w, i) => `${i + 1}. ${w}`).join("\n")}\n` : ""}
REFERENCES
${result.references.map((r, i) => `${i + 1}. ${r}`).join("\n")}`;
  exportAssessmentPDF({ title: "Vasectomy Reversal Clinical Compass", filename: "vasectomy-reversal-assessment.pdf", content });
};
